
on conflict(page_key,section_key) do update set title=excluded.title,subtitle=excluded.subtitle,content=excluded.content,sort_order=excluded.sort_order,is_published=excluded.is_published;

on conflict(slug) do update set title=excluded.title,short_description=excluded.short_description,description=excluded.description,icon=excluded.icon,tags=excluded.tags,sort_order=excluded.sort_order,is_published=excluded.is_published;
